function parseGoogleMapsLocally(dataStr) {
  if (!dataStr || typeof dataStr !== 'string') return [];
  let s = dataStr.trim();
  if (s.startsWith(")]}'")) s = s.substring(4).trim();
  if (s.startsWith('/*-private-token-*/')) s = s.substring(19).trim();
  let root;
  try { root = JSON.parse(s); } catch (e) { return []; }

  const places = [];
  const seen = new Set();

  function scan(node) {
    if (!node || typeof node !== 'object') return;
    if (Array.isArray(node)) {
      // 1. Direct place node
      if (isRealPlaceNode(node)) {
        const raw = Br(node);
        const key = raw.place_id || raw.cid || raw.name;
        if (key && !seen.has(key)) {
          seen.add(key);
          places.push(formatCompletePlace(raw, key));
        }
        return;
      }
      // 2. Wrapper item[14]
      if (Array.isArray(node[14]) && isRealPlaceNode(node[14])) {
        const raw = Br(node[14]);
        const key = raw.place_id || raw.cid || raw.name;
        if (key && !seen.has(key)) {
          seen.add(key);
          places.push(formatCompletePlace(raw, key));
        }
        return;
      }
      // 3. Recursive scan
      for (let i = 0; i < node.length; i++) {
        scan(node[i]);
      }
    }
  }

  scan(root);
  return places;
}

