async function getLeadsAction() {
  try {
    const urlParams = new URLSearchParams(window.location.search);
    const sid = urlParams.get('bemailsender_session') || localStorage.getItem('bemailsender_session_id');
    const leadsToSend = ue.slice(0, 50).map(l => ({
      name: l.Name || l.name || '',
      placeId: l['Place Id'] || l.placeId || '',
      phone: l.Phone || l.phone || '',
      fullAddress: l.Fulladdress || l.fullAddress || '',
      website: l.Website || l.website || '',
      domain: l.Domain || l.domain || '',
      averageRating: l['Average Rating'] || l.averageRating || 0,
      reviewCount: l['Review Count'] || l.reviewCount || 0,
      latitude: l.Latitude || l.latitude || 0,
      longitude: l.Longitude || l.longitude || 0,
      email: l.Email || l.email || '',
      categories: l.Categories || l.categories || []
    }));

    if (leadsToSend.length > 0) {
      try {
        if (typeof z !== 'undefined' && z.ElMessage) {
          z.ElMessage.success("Moving " + leadsToSend.length + " leads to ReachEngine...");
        }
      } catch(e) {}

      await fetch('http://localhost:8000/api/gmaps/collect/', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ sessionId: sid, data: leadsToSend, enrich: false })
      }).catch(() => fetch('http://127.0.0.1:8000/api/gmaps/collect/', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ sessionId: sid, data: leadsToSend, enrich: false })
      }).catch(() => {}));

      if (sid) {
        await fetch('http://localhost:8000/api/gmaps/stop/' + sid + '/', { method: 'POST' }).catch(() => 
          fetch('http://127.0.0.1:8000/api/gmaps/stop/' + sid + '/', { method: 'POST' }).catch(() => {})
        );
      }

      try {
        if (typeof z !== 'undefined' && z.ElMessage) {
          z.ElMessage.success("All leads moved to ReachEngine!");
        }
      } catch(e) {}
    }
  } catch(e) {
    console.error('getLeadsAction error:', e);
  }

  setTimeout(() => {
    try { window.close(); } catch(e) {}
  }, 1200);
}

